-- DB08 F4 ordered school policy approval.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(25);
SELECT ok(has_function_privilege('authenticated','app.request_finance_fee_change(uuid,uuid,numeric,date,date,uuid,uuid[],text,text)','EXECUTE'),'checked chain RPC available to authenticated');
SELECT ok(NOT has_function_privilege('service_role','app.request_finance_fee_change(uuid,uuid,numeric,date,date,uuid,uuid[],text,text)','EXECUTE'),'service role cannot submit chain');
\ir fixture_commands.sql
\ir fixture_change.sql
\ir fixture_chain.sql
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.configure_finance_fee('08000000-0000-4000-8000-000000000003','08000000-0000-4000-8000-000000000004','TUITION','Tuition','CHAIN_FEE','MONTHLY',2,10000,'2026-01-01','2026-12-31','Initial tuition','f4-initial')) AS x(source_id uuid,resource_id uuid,campus_id uuid) \gset fee_
RESET ROLE;
SELECT throws_ok($test$SELECT app.request_finance_fee_change((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE'),(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE') AND revision=1),12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021','08000000-0000-4000-8000-000000000021']::uuid[],'Approved chain price','chain-price')$test$,'P0001'::char(5),NULL::text,'duplicate reviewer in chain denied');
SELECT throws_ok($test$SELECT app.request_finance_fee_change((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE'),(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE') AND revision=1),12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021']::uuid[],'Approved chain price','chain-price')$test$,'P0001'::char(5),NULL::text,'wrong reviewer count denied');
SELECT throws_ok($test$SELECT app.request_finance_fee_change((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE'),(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE') AND revision=1),12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021','08000000-0000-4000-8000-000000000007']::uuid[],'Approved chain price','chain-price')$test$,'P0001'::char(5),NULL::text,'requester in chain denied');
SELECT throws_ok($test$SELECT app.request_finance_fee_change((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE'),(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE') AND revision=1),12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045','08000000-0000-4000-8000-000000000021'::uuid,'Approved chain price','old-one-step')$test$,'P0001'::char(5),NULL::text,'single reviewer command cannot bypass two-step policy');
SELECT id AS rev1 FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid AND revision=1 \gset
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.request_finance_fee_change(:'fee_resource_id'::uuid,:'rev1'::uuid,12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021','08000000-0000-4000-8000-000000000041']::uuid[],'Approved chain price','chain-price')) AS x(request_id uuid,state text,request_version bigint) \gset chain_
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.approval_request_steps WHERE request_id=:'chain_request_id'::uuid),2::bigint,'two ordered reviewer steps retained');
SELECT is((SELECT state FROM app_private.approval_request_steps WHERE request_id=:'chain_request_id'::uuid AND step_number=1),'OPEN'::text,'first review step opens');
SELECT is((SELECT state FROM app_private.approval_request_steps WHERE request_id=:'chain_request_id'::uuid AND step_number=2),'WAITING'::text,'second review step waits');
SELECT is((SELECT count(*) FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid),1::bigint,'pending chain has no new price');
SELECT is((app.request_finance_fee_change((SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE'),(SELECT id FROM app_private.finance_fee_rule_revisions WHERE rule_id=(SELECT id FROM app_private.finance_fee_rules WHERE rule_key='CHAIN_FEE') AND revision=1),12500,'2026-11-01','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021','08000000-0000-4000-8000-000000000041']::uuid[],'Approved chain price','chain-price')->>'request_id')::uuid,:'chain_request_id'::uuid,'chain exact request replay');
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SELECT throws_ok($test$SELECT app.review_finance_fee_change((SELECT request_id FROM app_private.finance_fee_change_intents),'APPROVE',(SELECT row_version FROM app_private.approval_requests WHERE id=(SELECT request_id FROM app_private.finance_fee_change_intents)),'Independent review','out-of-order')$test$,'P0001'::char(5),NULL::text,'second reviewer cannot act before first');
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.review_finance_fee_change(:'chain_request_id'::uuid,'APPROVE',:'chain_request_version'::bigint,'Independent review','first-step')) AS x(request_id uuid,state text,request_version bigint) \gset first_
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid),1::bigint,'first approval cannot publish price');
SELECT is((SELECT state FROM app_private.approval_requests WHERE id=:'chain_request_id'::uuid),'PENDING'::text,'request remains pending after first approval');
SELECT is((SELECT state FROM app_private.approval_request_steps WHERE request_id=:'chain_request_id'::uuid AND step_number=2),'OPEN'::text,'next reviewer opens after first approval');
SELECT is((SELECT count(*) FROM app_private.approval_reviews v JOIN app_private.approval_request_steps s ON s.id=v.step_id WHERE s.request_id=:'chain_request_id'::uuid),1::bigint,'first decision retained');
SELECT is((app.review_finance_fee_change(:'chain_request_id'::uuid,'APPROVE',:'chain_request_version'::bigint,'Independent review','first-step')->>'request_version')::bigint,:'first_request_version'::bigint,'intermediate exact replay');
SELECT throws_ok($test$SELECT app.review_finance_fee_change((SELECT request_id FROM app_private.finance_fee_change_intents),'APPROVE',(SELECT row_version FROM app_private.approval_requests WHERE id=(SELECT request_id FROM app_private.finance_fee_change_intents)),'Independent review','different-key-first')$test$,'P0001'::char(5),NULL::text,'first reviewer cannot act as second');
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SET ROLE authenticated;
SELECT * FROM jsonb_to_record(app.review_finance_fee_change(:'chain_request_id'::uuid,'APPROVE',:'first_request_version'::bigint,'Independent review','final-step')) AS x(request_id uuid,state text,request_version bigint,publication_id uuid) \gset final_
RESET ROLE;
SELECT is((SELECT count(*) FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid AND revision=2 AND gross_amount_minor=12500),1::bigint,'final approval publishes successor');
SELECT is((SELECT state FROM app_private.approval_requests WHERE id=:'chain_request_id'::uuid),'EXECUTED'::text,'final request executed');
SELECT is((SELECT count(*) FROM app_private.approval_reviews v JOIN app_private.approval_request_steps s ON s.id=v.step_id WHERE s.request_id=:'chain_request_id'::uuid AND v.decision='APPROVE'),2::bigint,'two independent decisions retained');
SELECT is((app.review_finance_fee_change(:'chain_request_id'::uuid,'APPROVE',:'first_request_version'::bigint,'Independent review','final-step')->>'publication_id')::uuid,:'final_publication_id'::uuid,'final exact replay');
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000008'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000008'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000008'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SELECT id AS rev2 FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid AND revision=2 \gset
SELECT * FROM jsonb_to_record(app.request_finance_fee_change(:'fee_resource_id'::uuid,:'rev2'::uuid,13000,'2026-12-15','2026-12-31','08000000-0000-4000-8000-000000000045',ARRAY['08000000-0000-4000-8000-000000000021','08000000-0000-4000-8000-000000000041']::uuid[],'Approved chain price','reject-chain')) AS x(request_id uuid,state text,request_version bigint) \gset reject_
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000022'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SELECT * FROM jsonb_to_record(app.review_finance_fee_change(:'reject_request_id'::uuid,'APPROVE',:'reject_request_version'::bigint,'Independent review','reject-first')) AS x(request_id uuid,state text,request_version bigint) \gset reject_mid_
SELECT set_config('request.jwt.claim.sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT auth_user_id::text FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'role','authenticated','iat',(SELECT extract(epoch FROM tokens_valid_from)::bigint FROM app_private.principal_auth_bindings WHERE id='08000000-0000-4000-8000-000000000044'),'exp',floor(extract(epoch FROM clock_timestamp()+interval '1 hour'))::bigint,'is_anonymous',false)::text,true);
SELECT app.review_finance_fee_change(:'reject_request_id'::uuid,'REJECT',:'reject_mid_request_version'::bigint,'Independent review','reject-final');
SELECT is((SELECT count(*) FROM app_private.finance_fee_rule_revisions WHERE rule_id=:'fee_resource_id'::uuid),2::bigint,'second-step rejection leaves price unchanged');
SELECT is((SELECT state FROM app_private.approval_requests WHERE id=:'reject_request_id'::uuid),'REJECTED'::text,'second-step rejection retained');
SELECT is((SELECT count(*) FROM app_private.command_receipts WHERE command_kind='finance.fee.change.review'),4::bigint,'four reviewer decisions have exact receipts');
SELECT * FROM finish();
ROLLBACK;
